pluginManagement {
    // Plugin versions are pinned in gradle.properties, which is not readable from a plugins {} block.
    val pinnedPluginVersions = java.util.Properties().apply {
        val propertiesFile = file("gradle.properties")
        if (propertiesFile.exists()) {
            propertiesFile.inputStream().use { load(it) }
        }
    }

    plugins {
        id("com.github.spotbugs") version pinnedPluginVersions.getProperty("spotbugsPluginVersion")
    }
}

plugins {
    // Apply the foojay-resolver plugin to allow automatic download of JDKs
    id("org.gradle.toolchains.foojay-resolver-convention") version "1.0.0"
}

rootProject.name = "YueMi-MC-Libs"
include("core-api")
include("core-plugin")
include("module-platform")
include("module-folia")
include("module-economy")
include("module-items")
include("module-gui")
include("module-event")
include("module-general")
